        seq_cnt = 0;
        for (wi = 0; wi < 256; wi = wi + 1) begin
            if (hist_pwm_5Fout[hist_idx_hist_pwm_5Fout - 1 - wi] === 64'h1) seq_cnt = seq_cnt + 1;
        end
        checks = checks + 1;
        if (seq_cnt != 255) begin fails = fails + 1; $display("CHECK duty_max_ratio#0 FAIL (seq_count top_pwm_out)"); end else $display("CHECK duty_max_ratio#0 PASS");

        // 收尾约定：运行护栏按这一行判红绿（不是退出码：$finish 恒返回 0）。
        $display("RESULT: checks=%0d fails=%0d", checks, fails);
        if (fails != 0) $fatal(1, "TB failed");
        $finish;
    end

`ifdef DUMP_VCD
    initial begin
        $dumpfile("tb_pwm_example.vcd");
        $dumpvars(0, tb_pwm_example);
    end
`endif

endmodule
